/* Maré de Estudos: dados da estudante ficam neste navegador. */
const DB_NAME='mare-de-estudos-v1';
const DB_VERSION=1;
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={view:'overview',questions:[],attempts:[],dataset:'demo',filter:{query:'',topic:'Todos',type:'multiple'},question:null,selected:null,submitted:false,openText:'',showModel:false,profile:{name:'',goal:10,minutes:45,exam:''},time:{},db:null};
const views={overview:'Visão geral',practice:'Resolver questões',errors:'Caderno de erros',results:'Resultados',history:'Histórico',settings:'Meu plano e dados'};

function dbOpen(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('attempts'))db.createObjectStore('attempts',{keyPath:'id'});if(!db.objectStoreNames.contains('content'))db.createObjectStore('content',{keyPath:'key'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbGetAll(name){return new Promise((resolve,reject)=>{const req=state.db.transaction(name,'readonly').objectStore(name).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbGet(name,key){return new Promise((resolve,reject)=>{const req=state.db.transaction(name,'readonly').objectStore(name).get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbPut(name,value){return new Promise((resolve,reject)=>{const req=state.db.transaction(name,'readwrite').objectStore(name).put(value);req.onsuccess=()=>resolve();req.onerror=()=>reject(req.error);});}
function dbClear(name){return new Promise((resolve,reject)=>{const req=state.db.transaction(name,'readwrite').objectStore(name).clear();req.onsuccess=()=>resolve();req.onerror=()=>reject(req.error);});}
const currentAttempts=()=>state.attempts.filter(a=>a.dataset===state.dataset);
function keyDay(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function monday(date=new Date()){const d=new Date(date.getFullYear(),date.getMonth(),date.getDate());d.setDate(d.getDate()-(d.getDay()+6)%7);return d;}
function weekKey(date=new Date()){return keyDay(monday(date));}
function inCurrentWeek(a){return weekKey(new Date(a.at))===weekKey();}
function firstAttempts(attempts=currentAttempts()){const seen=new Set();return [...attempts].sort((a,b)=>a.at.localeCompare(b.at)).filter(a=>{if(seen.has(a.questionId))return false;seen.add(a.questionId);return true;});}
function objectiveFirst(){return firstAttempts().filter(a=>a.type==='multiple');}
function answeredIds(){return new Set(firstAttempts().map(a=>a.questionId));}
function unresolvedErrors(){const byQuestion=new Map();for(const a of currentAttempts().sort((a,b)=>a.at.localeCompare(b.at)))byQuestion.set(a.questionId,a);return [...byQuestion.values()].filter(a=>a.correct===false).map(a=>({attempt:a,question:state.questions.find(q=>q.id===a.questionId)})).filter(x=>x.question);}
function pct(part,total){return total?`${(part/total*100).toFixed(1).replace('.',',')}%`:'—';}
function fmtDate(value){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value));}
function fmtTime(sec){const m=Math.floor(sec/60);return m>=60?`${Math.floor(m/60)} h ${m%60} min`:`${m} min`;}
function notice(){return state.dataset==='demo'?'<div class="demo-note"><span aria-hidden="true">◈</span><span><strong>Banco de demonstração:</strong> 12 questões baseadas em páginas da NOAA. Elas servem para testar o site; ainda não representam o conteúdo nem o estilo da prova da professora. Quando os materiais chegarem, substituiremos este banco.</span></div>':'';}
function header(title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">MARÉ DE ESTUDOS / FITOPLÂNCTON</p><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function sourceLink(q){const u=q.source?.url;return u&&/^https:\/\//.test(u)?`<a href="${escapeHTML(u)}" target="_blank" rel="noopener noreferrer">${escapeHTML(q.source.title||'Abrir fonte')} ↗</a>`:`<span>${escapeHTML(q.source?.title||'Material da disciplina')}${q.source?.locator?' · '+escapeHTML(q.source.locator):''}</span>`;}
function renderOverview(){const first=firstAttempts(),week=first.filter(inCurrentWeek),objWeek=objectiveFirst().filter(inCurrentWeek),correct=objWeek.filter(a=>a.correct).length,goal=Math.max(1,Number(state.profile.goal)||10),miss=unresolvedErrors();const topicItems=[...new Set(state.questions.map(q=>q.topic))].map(t=>{const qs=new Set(state.questions.filter(q=>q.topic===t).map(q=>q.id)),all=objectiveFirst().filter(a=>qs.has(a.questionId));return {name:t,done:all.length,right:all.filter(a=>a.correct).length};}).filter(t=>t.done).sort((a,b)=>a.right/a.done-b.right/b.done).slice(0,4);const mins=Object.entries(state.time).filter(([d])=>weekKey(new Date(d+'T12:00:00'))===weekKey()).reduce((s,[,v])=>s+v,0);return `${header(`Olá${state.profile.name?', '+escapeHTML(state.profile.name):''}.`,`Seu estudo da semana, sem misturar questões inéditas e revisões.`,`<button class="btn" data-action="start">Resolver questões <span aria-hidden="true">→</span></button>`)}${notice()}<div class="overview-grid"><section class="feature panel"><p class="eyebrow">PRÓXIMO PASSO</p><h2>${miss.length?'Revise um ponto que ficou em aberto.':'Uma questão de cada vez, com direção.'}</h2><p>${miss.length?`Você tem ${miss.length} ${miss.length===1?'questão pendente':'questões pendentes'} no caderno de erros. A correção indica onde retomar a leitura.`:'Priorize questões que você ainda não resolveu. A correção fica disponível após cada resposta.'}</p><button class="btn" data-action="${miss.length?'go-errors':'start'}">${miss.length?'Abrir caderno de erros':'Começar a praticar'} →</button></section><section class="goal-card panel"><div class="card-top"><span class="label">META DA SEMANA</span><span class="badge">${Math.min(100,Math.round(week.length/goal*100))}%</span></div><h2>${week.length}<span> / ${goal} questões</span></h2><p>Primeiras tentativas nesta semana</p><div class="progress-track"><i style="width:${Math.min(100,week.length/goal*100)}%"></i></div><div class="goal-footer"><span>${Math.max(0,goal-week.length)} para concluir</span><span>Meta ajustável</span></div></section></div><div class="stats-grid"><section class="stat panel"><span class="label">ACERTOS NA SEMANA</span><strong>${pct(correct,objWeek.length)}</strong><small>${correct} de ${objWeek.length} objetivas inéditas</small></section><section class="stat panel"><span class="label">QUESTÕES FEITAS</span><strong>${first.length}</strong><small>Primeiras tentativas no total</small></section><section class="stat panel"><span class="label">PARA REVISAR</span><strong>${miss.length}</strong><small>Erros ainda não corrigidos</small></section><section class="stat panel"><span class="label">TEMPO ATIVO</span><strong>${fmtTime(mins)}</strong><small>Com a página visível nesta semana</small></section></div><div class="split-grid"><section class="section-panel panel"><div class="section-head"><h2>Desempenho por assunto</h2><button class="text-link" data-action="go-results">Ver resultados →</button></div>${topicItems.length?topicItems.map(t=>`<div class="topic-row"><b>${escapeHTML(t.name)}</b><div class="progress-track"><i style="width:${t.right/t.done*100}%"></i></div><em>${pct(t.right,t.done)}</em></div>`).join(''):'<p class="empty-message">Ao resolver questões objetivas, você verá os acertos em cada assunto.</p>'}</section><section class="section-panel panel"><div class="section-head"><h2>Retomar a leitura</h2><button class="text-link" data-action="go-errors">Caderno de erros →</button></div><div class="review-list">${miss.length?miss.slice(0,3).map(x=>`<div class="review-item"><strong>${escapeHTML(x.question.topic)} · ${escapeHTML(x.question.prompt)}</strong><small>${escapeHTML(x.question.reading||'Revise a explicação da questão.')}</small></div>`).join(''):'<p class="empty-message">As leituras recomendadas para questões erradas aparecem aqui.</p>'}</div></section></div>`;}
function filteredQuestions(){const f=state.filter,q=f.query.trim().toLocaleLowerCase('pt-BR');return state.questions.filter(x=>(f.type==='all'||x.type===f.type)&&(f.topic==='Todos'||x.topic===f.topic)&&(!q||[x.id,x.topic,x.prompt].some(s=>String(s).toLocaleLowerCase('pt-BR').includes(q))));}
function nextQuestion(review=false){const pool=review?unresolvedErrors().map(x=>x.question).filter(q=>filteredQuestions().some(f=>f.id===q.id)):filteredQuestions().filter(q=>!answeredIds().has(q.id));if(!pool.length){state.question=null;return;}state.question=pool[Math.floor(Math.random()*pool.length)];state.selected=null;state.submitted=false;state.openText='';state.showModel=false;}
function renderPractice(){const topics=['Todos',...new Set(state.questions.map(q=>q.topic))],pool=filteredQuestions(),unseen=pool.filter(q=>!answeredIds().has(q.id));if(state.question&&!pool.some(q=>q.id===state.question.id))state.question=null;if(!state.question&&unseen.length)nextQuestion();const q=state.question;return `${header('Resolver questões','Busque por número, texto ou assunto. O sorteio usa questões inéditas primeiro.')}${notice()}<div class="toolbar"><input class="field search-field" type="search" id="question-search" placeholder="Buscar assunto ou questão..." value="${escapeHTML(state.filter.query)}" aria-label="Buscar questão" /><select class="field" id="topic-filter" aria-label="Filtrar assunto">${topics.map(t=>`<option value="${escapeHTML(t)}" ${state.filter.topic===t?'selected':''}>${escapeHTML(t==='Todos'?'Todos os assuntos':t)}</option>`).join('')}</select><select class="field" id="type-filter" aria-label="Filtrar tipo"><option value="multiple" ${state.filter.type==='multiple'?'selected':''}>Múltipla escolha</option><option value="open" ${state.filter.type==='open'?'selected':''}>Discursivas</option><option value="all" ${state.filter.type==='all'?'selected':''}>Todos os tipos</option></select></div><div class="filters-foot"><span>${pool.length} ${pool.length===1?'questão encontrada':'questões encontradas'} · ${unseen.length} inéditas</span><span>Revisões ficam no caderno de erros</span></div>${q?`<div class="question-layout"><section class="question-card panel"><div class="question-meta"><span class="badge">${escapeHTML(q.topic)}</span><span class="badge warm">${escapeHTML(q.difficulty||'Sem nível')}</span><span class="question-id">${escapeHTML(q.id)}</span></div><h2>${escapeHTML(q.prompt)}</h2>${q.type==='multiple'?renderMultiple(q):renderOpen(q)}</section><aside class="context-card panel"><h3>Sua prática</h3><p>Questões inéditas aparecem antes de qualquer repetição. Quando você errar, a indicação de leitura fica salva no caderno.</p><div class="mini-stat"><span>Neste filtro</span><b>${pool.length}</b></div><div class="mini-stat"><span>Ainda inéditas</span><b>${unseen.length}</b></div><div class="mini-stat"><span>Para revisar</span><b>${unresolvedErrors().length}</b></div></aside></div>`:`<div class="empty-state panel"><h2>${pool.length?'Você concluiu as questões inéditas deste filtro.':'Nenhuma questão neste filtro.'}</h2><p>${pool.length?'Seu histórico foi mantido. Para reforçar o conteúdo, abra o caderno de erros ou escolha outro filtro. Quando chegarem os materiais da disciplina, este banco será ampliado.':'Tente outro termo, assunto ou tipo de questão.'}</p><button class="btn light" data-action="${pool.length?'go-errors':'clear-filter'}">${pool.length?'Revisar erros':'Limpar filtros'}</button></div>`}`;}
function renderMultiple(q){return `<div class="choices" role="group" aria-label="Alternativas">${q.options.map((opt,i)=>`<button type="button" class="choice ${state.selected===i?'selected':''} ${state.submitted?(i===q.answer?'correct':state.selected===i?'wrong':''):''}" data-action="choose" data-index="${i}" ${state.submitted?'disabled':''}><span class="choice-letter">${'ABCD'[i]||i+1}</span><span>${escapeHTML(opt)}</span></button>`).join('')}</div>${state.submitted?feedback(q,state.selected===q.answer):''}<div class="question-actions">${!state.submitted?'<button class="btn" data-action="submit-choice" '+(state.selected===null?'disabled':'')+'>Corrigir resposta</button>':'<button class="btn" data-action="next">Próxima questão →</button>'}</div>`;}
function renderOpen(q){return `<textarea class="answer-box" id="open-answer" placeholder="Escreva sua resposta antes de consultar o modelo..." aria-label="Sua resposta" ${state.showModel?'readonly':''}>${escapeHTML(state.openText)}</textarea>${!state.showModel?'<div class="question-actions"><button class="btn" data-action="show-model">Comparar com o modelo</button></div>':`<div class="feedback"><h3>Resposta de referência</h3><p>${escapeHTML(q.model)}</p><p class="reading"><strong>Onde reler:</strong> ${escapeHTML(q.reading)}<br />${sourceLink(q)}</p></div>${state.submitted?'<div class="feedback"><h3>Autoavaliação salva.</h3><p>Veja a nota no histórico. Ela não entra na taxa das objetivas.</p></div><div class="question-actions"><button class="btn" data-action="next">Próxima questão →</button></div>':`<div class="model-box"><strong>Autoavaliação</strong><p>Marque apenas os pontos que você explicou corretamente. A pontuação indica sua própria conferência, não uma correção automática.</p><div class="self-check">${q.criteria.map((c,i)=>`<label><input type="checkbox" data-criterion="${i}" /><span>${escapeHTML(c)}</span></label>`).join('')}</div><strong id="self-score">0 de 10 pontos</strong></div><div class="question-actions"><button class="btn" data-action="save-open">Salvar autoavaliação</button></div>`}`}`;}
function feedback(q,correct){return `<div class="feedback ${correct?'':'incorrect'}"><h3>${correct?'Você acertou.':'Vale retomar este ponto.'}</h3><p>${escapeHTML(q.explanation)}</p><p class="reading"><strong>Onde reler:</strong> ${escapeHTML(q.reading)}<br />${sourceLink(q)}</p></div>`;}
function renderErrors(){const errors=unresolvedErrors();return `${header('Caderno de erros','Cada item guarda a explicação e um caminho de leitura para tentar novamente.')}${notice()}${errors.length?`<div class="panel section-panel"><div class="section-head"><h2>${errors.length} ${errors.length===1?'questão pendente':'questões pendentes'}</h2><span class="badge warm">Revisão dirigida</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Questão</th><th>Onde reler</th><th>Última tentativa</th><th></th></tr></thead><tbody>${errors.map(({question:q,attempt:a})=>`<tr><td><strong>${escapeHTML(q.prompt)}</strong><small>${escapeHTML(q.topic)} · ${escapeHTML(q.id)}</small></td><td>${escapeHTML(q.reading||'Consulte a explicação.')}</td><td>${fmtDate(a.at)}</td><td><button class="btn light" data-action="retry" data-id="${escapeHTML(q.id)}">Refazer</button></td></tr>`).join('')}</tbody></table></div></div>`:`<div class="empty-state panel"><h2>Nenhuma questão pendente de revisão.</h2><p>Quando você errar uma questão, ela aparecerá aqui com a explicação e uma sugestão de leitura.</p><button class="btn" data-action="start">Resolver questões</button></div>`}`;}
function renderResults(){const first=firstAttempts(),objective=objectiveFirst(),right=objective.filter(a=>a.correct).length,byTopic=[...new Set(state.questions.map(q=>q.topic))].map(t=>{const ids=new Set(state.questions.filter(q=>q.topic===t).map(q=>q.id)),a=objective.filter(x=>ids.has(x.questionId));return {topic:t,total:a.length,right:a.filter(x=>x.correct).length};});const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const date=keyDay(d),items=first.filter(a=>keyDay(new Date(a.at))===date);return {date,label:new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(d).replace('.',''),total:items.length,right:items.filter(a=>a.correct).length};});const totalTime=Object.values(state.time).reduce((a,b)=>a+b,0);return `${header('Resultados','Acertos calculados nas objetivas inéditas. Discursivas ficam separadas no histórico.')}${notice()}<div class="stats-grid"><section class="stat panel"><span class="label">ACERTO GERAL</span><strong>${pct(right,objective.length)}</strong><small>${right} de ${objective.length} objetivas inéditas</small></section><section class="stat panel"><span class="label">QUESTÕES RESPONDIDAS</span><strong>${currentAttempts().length}</strong><small>${first.length} inéditas · ${currentAttempts().length-first.length} revisões</small></section><section class="stat panel"><span class="label">PONTOS A REVER</span><strong>${unresolvedErrors().length}</strong><small>Última tentativa incorreta</small></section><section class="stat panel"><span class="label">TEMPO REGISTRADO</span><strong>${fmtTime(totalTime)}</strong><small>Tempo ativo neste navegador</small></section></div><div class="split-grid"><section class="section-panel panel"><div class="section-head"><h2>Acertos por assunto</h2><span class="label">OBJETIVAS · PRIMEIRA TENTATIVA</span></div>${byTopic.filter(t=>t.total).length?byTopic.filter(t=>t.total).map(t=>`<div class="topic-row"><b>${escapeHTML(t.topic)}</b><div class="progress-track"><i style="width:${t.right/t.total*100}%"></i></div><em title="${t.right} de ${t.total}">${pct(t.right,t.total)}</em></div>`).join(''):'<p class="empty-message">Ainda não há respostas para comparar os assuntos.</p>'}<p class="small-print">Considere também o número de questões: uma única resposta não define domínio de um assunto.</p></section><section class="section-panel panel"><div class="section-head"><h2>Últimos 7 dias</h2><span class="label">QUESTÕES INÉDITAS</span></div><div class="trend" role="img" aria-label="Questões inéditas resolvidas nos últimos sete dias">${days.map(d=>`<div class="trend-col"><strong>${d.total||''}</strong><div class="trend-bar" style="height:${Math.max(3,d.total/Math.max(1,...days.map(x=>x.total))*110)}px" title="${d.total} em ${d.date}"></div><span>${d.label}</span></div>`).join('')}</div></section></div>`;}
function renderHistory(){const list=[...currentAttempts()].sort((a,b)=>b.at.localeCompare(a.at));return `${header('Histórico','Todas as tentativas ficam registradas neste navegador.')}${notice()}${list.length?`<div class="section-panel panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Quando</th><th>Questão</th><th>Resultado</th><th>Tentativa</th></tr></thead><tbody>${list.map(a=>{const q=state.questions.find(x=>x.id===a.questionId);return `<tr><td>${fmtDate(a.at)}</td><td><strong>${escapeHTML(q?.prompt||a.questionId)}</strong><small>${escapeHTML(q?.topic||'Questão anterior')}</small></td><td><span class="badge ${a.correct?'':'red'}">${a.type==='open'?`${a.score}/10 · autoavaliação`:a.correct?'Acertou':'Errou'}</span></td><td>${a.first?'Primeira':'Revisão'}</td></tr>`;}).join('')}</tbody></table></div></div>`:'<div class="empty-state panel"><h2>Seu histórico começa na primeira resposta.</h2><p>As tentativas, inclusive revisões, aparecerão aqui em ordem de data.</p><button class="btn" data-action="start">Começar</button></div>'}`;}
function renderSettings(){return `${header('Meu plano e dados','Ajuste sua meta e guarde uma cópia do progresso.')}${notice()}<div class="settings-grid"><section class="panel"><h2>Plano de estudo</h2><p>A meta ajuda a organizar a semana. Você pode mudá-la conforme o tempo disponível.</p><div class="form-row"><label for="profile-name">Como prefere ser chamada?</label><input class="field" id="profile-name" maxlength="36" value="${escapeHTML(state.profile.name)}" placeholder="Seu nome" /></div><div class="form-row"><label for="profile-goal">Questões inéditas por semana</label><input class="field" id="profile-goal" type="number" min="1" max="500" value="${escapeHTML(state.profile.goal)}" /></div><div class="form-row"><label for="profile-minutes">Minutos disponíveis por dia</label><input class="field" id="profile-minutes" type="number" min="5" max="600" value="${escapeHTML(state.profile.minutes)}" /></div><div class="form-row"><label for="profile-exam">Data da prova (opcional)</label><input class="field" id="profile-exam" type="date" value="${escapeHTML(state.profile.exam)}" /></div><button class="btn" data-action="save-profile">Salvar plano</button></section><section class="panel"><h2>Conteúdo e backup</h2><p>${state.dataset==='demo'?'O banco atual tem 12 questões de demonstração.':'O banco atual contém '+state.questions.length+' questões importadas.'} Um novo banco pode incluir múltipla escolha e discursivas, com correção e indicação de leitura.</p><button class="btn light" data-action="import">Importar banco de questões (.json)</button><p class="small-print">A importação substitui o banco exibido; o histórico anterior permanece guardado separadamente e não entra nas estatísticas do novo banco. Envie os PDFs para prepararmos as questões antes de importar.</p><button class="btn ghost" data-action="export">Baixar backup do progresso</button><p class="small-print">O progresso fica apenas neste navegador. O backup inclui tentativas, plano, tempo e banco importado.</p><button class="text-link" data-action="restore">Restaurar backup</button></section></div>`;}
function render(){const app=$('#app-content');if(!app)return;app.innerHTML=({overview:renderOverview,practice:renderPractice,errors:renderErrors,results:renderResults,history:renderHistory,settings:renderSettings}[state.view])();$('#crumb-current').textContent=views[state.view];document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#nav-count').textContent=state.questions.length;$('#active-time').textContent=`◷ ${fmtTime(Object.values(state.time).reduce((a,b)=>a+b,0))}`;}
function setView(view){state.view=view;if(view==='practice'){state.question=null;state.selected=null;}$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();$('#app-content').focus({preventScroll:true});}
async function saveAttempt(data){const a={id:crypto.randomUUID(),dataset:state.dataset,questionId:state.question.id,type:state.question.type,at:new Date().toISOString(),first:!answeredIds().has(state.question.id),...data};await dbPut('attempts',a);state.attempts.push(a);render();}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function safeQuestion(x){return x&&typeof x.id==='string'&&x.id.length<100&&typeof x.prompt==='string'&&x.prompt.length<2000&&typeof x.topic==='string'&&['multiple','open'].includes(x.type)&&typeof x.reading==='string'&&x.reading.length<3000&&x.source&&typeof x.source.title==='string'&&(x.type==='multiple'?Array.isArray(x.options)&&x.options.length>=2&&x.options.length<=6&&x.options.every(v=>typeof v==='string')&&Number.isInteger(x.answer)&&x.answer>=0&&x.answer<x.options.length&&typeof x.explanation==='string':typeof x.model==='string'&&Array.isArray(x.criteria)&&x.criteria.length===3&&x.criteria.every(v=>typeof v==='string'));}
async function importQuestions(file,backup=false){if(file.size>5_000_000)throw Error('O arquivo é grande demais (limite: 5 MB).');const parsed=JSON.parse(await file.text());if(backup){if(parsed.format!=='mare-de-estudos-backup-v1'||!Array.isArray(parsed.attempts)||!parsed.attempts.every(a=>a&&typeof a.id==='string'&&typeof a.questionId==='string'&&typeof a.at==='string'))throw Error('Este arquivo não é um backup válido.');if(!Array.isArray(parsed.questions)||!parsed.questions.every(safeQuestion))throw Error('As questões do backup não são válidas.');if(parsed.questions.length){state.questions=parsed.questions;state.dataset=String(parsed.dataset||'restaurado');await dbPut('content',{key:'questions',dataset:state.dataset,items:state.questions});}await dbClear('attempts');for(const a of parsed.attempts)await dbPut('attempts',a);state.attempts=parsed.attempts;state.profile={...state.profile,...parsed.profile};state.time=parsed.time&&typeof parsed.time==='object'?parsed.time:{};localStorage.setItem('mare-profile',JSON.stringify(state.profile));localStorage.setItem('mare-time',JSON.stringify(state.time));toast('Backup restaurado.');}
else{const questions=Array.isArray(parsed)?parsed:parsed.questions;if(!Array.isArray(questions)||!questions.length||!questions.every(safeQuestion)||new Set(questions.map(q=>q.id)).size!==questions.length)throw Error('Banco inválido. Confira identificadores, tipos, gabaritos, explicações e fontes.');state.questions=questions;state.dataset=`import-${Date.now()}`;await dbPut('content',{key:'questions',dataset:state.dataset,items:questions});toast(`${questions.length} questões importadas.`);}state.question=null;setView('overview');}
function downloadBackup(){const data={format:'mare-de-estudos-backup-v1',exportedAt:new Date().toISOString(),dataset:state.dataset,questions:state.questions,attempts:state.attempts,profile:state.profile,time:state.time};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`mare-de-estudos-backup-${keyDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let importMode='questions';
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{if(action==='start'){setView('practice');return;}if(action==='go-errors'){setView('errors');return;}if(action==='go-results'){setView('results');return;}if(action==='clear-filter'){state.filter={query:'',topic:'Todos',type:'multiple'};state.question=null;render();return;}if(action==='choose'){state.selected=Number(b.dataset.index);render();return;}if(action==='submit-choice'){if(state.selected===null)return;const correct=state.selected===state.question.answer;state.submitted=true;await saveAttempt({correct,selected:state.selected});return;}if(action==='next'){state.question=null;nextQuestion();render();return;}if(action==='retry'){const q=state.questions.find(x=>x.id===b.dataset.id);if(!q)return;state.filter={query:'',topic:'Todos',type:'all'};state.view='practice';state.question=q;state.selected=null;state.submitted=false;state.showModel=false;state.openText='';render();return;}if(action==='show-model'){state.openText=$('#open-answer').value.trim();if(state.openText.length<20){toast('Escreva pelo menos uma frase antes de comparar.');return;}state.showModel=true;render();return;}if(action==='save-open'){const checked=[...document.querySelectorAll('[data-criterion]')].filter(el=>el.checked).length;state.submitted=true;await saveAttempt({correct:checked===3,score:Math.round(checked/3*10),answer:state.openText});return;}if(action==='save-profile'){const goal=Number($('#profile-goal').value),minutes=Number($('#profile-minutes').value);if(!Number.isInteger(goal)||goal<1||goal>500||!Number.isInteger(minutes)||minutes<5||minutes>600){toast('Confira a meta e os minutos informados.');return;}state.profile={name:$('#profile-name').value.trim(),goal,minutes,exam:$('#profile-exam').value};localStorage.setItem('mare-profile',JSON.stringify(state.profile));toast('Plano atualizado.');render();return;}if(action==='export'){downloadBackup();return;}if(action==='import'||action==='restore'){importMode=action==='restore'?'backup':'questions';$('#import-input').click();return;}}catch(error){console.error(error);toast('Não foi possível salvar. Tente novamente.');}});
document.addEventListener('change',e=>{if(e.target.id==='topic-filter'||e.target.id==='type-filter'){state.filter.topic=$('#topic-filter').value;state.filter.type=$('#type-filter').value;state.question=null;render();}if(e.target.matches('[data-criterion]')){$('#self-score').textContent=`${Math.round(document.querySelectorAll('[data-criterion]:checked').length/3*10)} de 10 pontos`;}});
document.addEventListener('input',e=>{if(e.target.id==='question-search'){const start=e.target.selectionStart;state.filter.query=e.target.value;state.question=null;render();const input=$('#question-search');input.focus();input.setSelectionRange(start,start);}});
$('#import-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{await importQuestions(file,importMode==='backup');}catch(error){console.error(error);toast(error.message||'Falha ao importar.');}e.target.value='';});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});

let lastInteraction=Date.now(),lastTick=Date.now(),dirtySeconds=0;
for(const name of ['pointerdown','keydown','scroll'])document.addEventListener(name,()=>{lastInteraction=Date.now();},{passive:true});
function tick(){const now=Date.now(),delta=Math.min(1000,Math.max(0,now-lastTick));lastTick=now;if(document.visibilityState==='visible'&&document.hasFocus()&&now-lastInteraction<120000){const day=keyDay();state.time[day]=(state.time[day]||0)+delta/1000;dirtySeconds+=delta/1000;if(dirtySeconds>=15){localStorage.setItem('mare-time',JSON.stringify(state.time));dirtySeconds=0;}$('#active-time').textContent=`◷ ${fmtTime(Object.values(state.time).reduce((a,b)=>a+b,0))}`;}}
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();if(document.visibilityState==='hidden')localStorage.setItem('mare-time',JSON.stringify(state.time));else lastInteraction=Date.now();});
window.addEventListener('pagehide',()=>localStorage.setItem('mare-time',JSON.stringify(state.time)));
async function init(){try{state.db=await dbOpen();const [saved,attempts,demo]=await Promise.all([dbGet('content','questions'),dbGetAll('attempts'),fetch('./questions.json').then(r=>{if(!r.ok)throw Error('Banco inicial indisponível');return r.json();})]);state.questions=saved?.items||demo;state.dataset=saved?.dataset||'demo';state.attempts=attempts;state.profile={...state.profile,...JSON.parse(localStorage.getItem('mare-profile')||'{}')};state.time=JSON.parse(localStorage.getItem('mare-time')||'{}');render();registerAgentTools();setInterval(tick,1000);}catch(error){console.error(error);$('#app-content').innerHTML='<div class="empty-state panel"><h2>Não foi possível abrir o banco local.</h2><p>Confira se este navegador permite guardar dados do site e recarregue a página.</p></div>';}}
function registerAgentTools(){const mc=document.modelContext;if(!mc?.registerTool)return;const tools=[{name:'read_study_progress',title:'Consultar progresso',description:'Lê a meta, as respostas objetivas inéditas e os assuntos que precisam de revisão neste navegador.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const objectives=objectiveFirst(),correct=objectives.filter(a=>a.correct).length;return {dataset:state.dataset,questions:state.questions.length,firstAttempts:firstAttempts().length,objectiveCorrect:correct,objectiveTotal:objectives.length,accuracy:objectives.length?correct/objectives.length:null,pendingReview:unresolvedErrors().length,weeklyGoal:state.profile.goal};}},{name:'start_question_practice',title:'Abrir uma questão',description:'Abre uma questão inédita de múltipla escolha na área visível de prática.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){state.filter={query:'',topic:'Todos',type:'multiple'};setView('practice');return state.question?{id:state.question.id,prompt:state.question.prompt,options:state.question.options}:{status:'no_unseen_questions'};}},{name:'submit_current_multiple_answer',title:'Responder questão atual',description:'Registra uma resposta objetiva na questão aberta e mostra a correção no site.',inputSchema:{type:'object',properties:{optionIndex:{type:'integer',minimum:0}},required:['optionIndex'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){const i=input?.optionIndex,q=state.question;if(state.view!=='practice'||!q||q.type!=='multiple'||state.submitted||!Number.isInteger(i)||i<0||i>=q.options.length)throw Error('Abra uma questão objetiva e informe uma alternativa válida ainda não respondida.');state.selected=i;state.submitted=true;await saveAttempt({correct:i===q.answer,selected:i});return {questionId:q.id,correct:i===q.answer,explanation:q.explanation,reading:q.reading};}}];for(const tool of tools){try{Promise.resolve(mc.registerTool(tool)).catch(console.warn);}catch(e){console.warn('Ferramenta indisponível',e);}}}
init();
